/**
 * HUD Fase — preview standalone + runtime Wicand (`window.__blkHtmlUi`).
 * Sync: vida, colete, municao, reserva, creditos, timer, inimigo_hp_1..5.
 * Esquerda = jogador (fantasia_escolhida). Direita = inimigos (agente 1..5).
 */

(function () {
  const AGENTS = {
    astra: { id: "astra", name: "Astra", img: "imgs/agents-mini-images/astra.png" },
    breach: { id: "breach", name: "Breach", img: "imgs/agents-mini-images/breach.png" },
    brimstone: { id: "brimstone", name: "Brimstone", img: "imgs/agents-mini-images/brimstone.png" },
    chamber: { id: "chamber", name: "Chamber", img: "imgs/agents-mini-images/chamber.png" },
    clove: { id: "clove", name: "Clove", img: "imgs/agents-mini-images/clove.png" },
    cypher: { id: "cypher", name: "Cypher", img: "imgs/agents-mini-images/cypher.png" },
    deadlock: { id: "deadlock", name: "Deadlock", img: "imgs/agents-mini-images/deadlock.png" },
    fade: { id: "fade", name: "Fade", img: "imgs/agents-mini-images/fade.png" },
    gekko: { id: "gekko", name: "Gekko", img: "imgs/agents-mini-images/gekko.png" },
    harbor: { id: "harbor", name: "Harbor", img: "imgs/agents-mini-images/harbor.png" },
    iso: { id: "iso", name: "Iso", img: "imgs/agents-mini-images/iso.png" },
    jett: { id: "jett", name: "Jett", img: "imgs/agents-mini-images/Jett.webp" },
    kayo: { id: "kayo", name: "KAY/O", img: "imgs/agents-mini-images/kayo.png" },
    killjoy: { id: "killjoy", name: "Killjoy", img: "imgs/agents-mini-images/killjoy.png" },
    neon: { id: "neon", name: "Neon", img: "imgs/agents-mini-images/neon.png" },
    omen: { id: "omen", name: "Omen", img: "imgs/agents-mini-images/omen.png" },
    phoenix: { id: "phoenix", name: "Phoenix", img: "imgs/agents-mini-images/phoenix.png" },
    raze: { id: "raze", name: "Raze", img: "imgs/agents-mini-images/raze.png" },
    reyna: { id: "reyna", name: "Reyna", img: "imgs/agents-mini-images/reyna.png" },
    sage: { id: "sage", name: "Sage", img: "imgs/agents-mini-images/sage.png" },
    skye: { id: "skye", name: "Skye", img: "imgs/agents-mini-images/skye.png" },
    sova: { id: "sova", name: "Sova", img: "imgs/agents-mini-images/sova.png" },
    viper: { id: "viper", name: "Viper", img: "imgs/agents-mini-images/viper.png" },
    vyse: { id: "vyse", name: "Vyse", img: "imgs/agents-mini-images/vyse.png" },
    yoru: { id: "yoru", name: "Yoru", img: "imgs/agents-mini-images/yoru.png" },
  };

  /**
   * Fantasias do ator Inimigo (switch-costume com `agente` 1-based):
   * 1 Brinstone, 2 Jett, 3 Phoenix, 4 Sage, 5 Reyna, 6 Omen
   */
  const ENEMY_AGENTE_TO_ID = {
    1: "brimstone",
    2: "jett",
    3: "phoenix",
    4: "sage",
    5: "reyna",
    6: "omen",
  };

  const TEAM_ALLY = [{ id: "jett", alive: true, hp: 100 }];
  const TEAM_ENEMY = [1, 2, 3, 4, 5].map(function (slot) {
    return { id: ENEMY_AGENTE_TO_ID[slot], alive: true, hp: 100, slot: slot };
  });

  window.HUD_AGENTS = AGENTS;

  const allyPortraitEls = [];
  const enemyPortraitEls = [];

  function normalizeAgentId(raw) {
    var id = String(raw || "")
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]/g, "");
    if (id === "brinstone") id = "brimstone";
    if (id === "kayo" || id === "kay/o") id = "kayo";
    return id;
  }

  function renderPortraits(container, lineup, isEnemy) {
    if (!container) return;
    container.innerHTML = "";
    var bucket = isEnemy ? enemyPortraitEls : allyPortraitEls;
    bucket.length = 0;
    lineup.forEach(function (slot) {
      const agent = AGENTS[slot.id];
      if (!agent) return;

      const el = document.createElement("div");
      el.className = "portrait" + (slot.alive === false ? " portrait--dim" : "");
      el.title = agent.name;
      el.dataset.agent = agent.id;
      if (slot.slot != null) el.dataset.slot = String(slot.slot);

      const img = document.createElement("img");
      img.className = "portrait__img";
      img.src = agent.img;
      img.alt = agent.name;
      img.draggable = false;

      const hp = document.createElement("span");
      hp.className =
        "portrait__hp" +
        (slot.alive === false ? " portrait__hp--dim" : "") +
        (isEnemy ? " portrait__hp--enemy" : " portrait__hp--ally");
      const fill = document.createElement("i");
      fill.className = "portrait__hp-fill";
      hp.appendChild(fill);

      el.appendChild(img);
      el.appendChild(hp);
      container.appendChild(el);

      bucket.push({ root: el, img: img, hp: hp, fill: fill, slot: slot });
    });
  }

  function setPortraitHp(entry, hp) {
    if (!entry) return;
    const maxHp = 100;
    const v = Math.max(0, Math.min(maxHp, Number(hp) || 0));
    const pct = v / maxHp;
    const alive = v >= 1;
    entry.slot.hp = v;
    entry.slot.alive = alive;
    entry.root.classList.toggle("portrait--dim", !alive);
    entry.hp.classList.toggle("portrait__hp--dim", !alive);
    if (entry.fill) entry.fill.style.transform = "scaleX(" + pct + ")";
  }

  function setEnemyAgent(slotIndex, agentId) {
    var entry = enemyPortraitEls[slotIndex];
    var slot = TEAM_ENEMY[slotIndex];
    if (!entry || !slot) return;
    var id = normalizeAgentId(agentId);
    if (!AGENTS[id] || slot.id === id) return;
    slot.id = id;
    entry.root.dataset.agent = id;
    entry.root.title = AGENTS[id].name;
    entry.img.src = AGENTS[id].img;
    entry.img.alt = AGENTS[id].name;
  }

  renderPortraits(document.getElementById("portraitsAlly"), TEAM_ALLY, false);
  renderPortraits(document.getElementById("portraitsEnemy"), TEAM_ENEMY, true);

  const timerEl = document.getElementById("timer");
  const scoreAllyEl = document.getElementById("scoreAlly");
  const scoreEnemyEl = document.getElementById("scoreEnemy");
  const banner = document.getElementById("roundBanner");
  const bannerTitle = banner ? banner.querySelector(".round-banner__title") : null;
  const bannerSub = banner ? banner.querySelector(".round-banner__sub") : null;
  const healthEl = document.getElementById("health");
  const shieldEl = document.getElementById("shield");
  const ammoMagEl = document.getElementById("ammoMag");
  const ammoReserveEl = document.getElementById("ammoReserve");
  const creditsEl = document.getElementById("credits");
  const weapons = Array.prototype.slice.call(document.querySelectorAll(".weapon"));

  let scoreAlly = 0;
  let scoreEnemy = 0;

  const bridge =
    typeof window.__blkHtmlUi === "object" && window.__blkHtmlUi
      ? window.__blkHtmlUi
      : null;
  const inGame = !!bridge;

  const ROUND_LENGTH = 100;
  let seconds = ROUND_LENGTH;
  let bannerHideAt = 0;
  let matchEnded = false;
  let usingGameTimer = false;
  /** Só libera fim de partida depois de ver a partida aberta (flag 0 e/ou timer > 0). */
  let matchReady = false;

  function formatTime(s) {
    const m = Math.floor(s / 60);
    const r = s % 60;
    return m + ":" + String(r).padStart(2, "0");
  }

  function readNum(name, fallback) {
    if (!bridge || typeof bridge.get !== "function") return fallback;
    const v = bridge.get(name);
    if (v == null || v === "") return fallback;
    const n = Number(v);
    return Number.isFinite(n) ? n : fallback;
  }

  function readStr(name, fallback) {
    if (!bridge || typeof bridge.get !== "function") return fallback;
    const v = bridge.get(name);
    if (v == null || v === "") return fallback;
    return String(v);
  }

  function setText(el, value) {
    if (!el) return;
    const next = String(value);
    if (el.textContent !== next) el.textContent = next;
  }

  function showMatchEnd() {
    if (matchEnded || !banner) return;
    if (inGame && !matchReady) return;
    matchEnded = true;
    var ally = scoreAlly;
    var enemy = scoreEnemy;
    banner.classList.remove("round-banner--win", "round-banner--lose", "round-banner--draw", "round-banner--end");
    if (ally > enemy) {
      if (bannerTitle) bannerTitle.textContent = "VITÓRIA";
      if (bannerSub) bannerSub.textContent = ally + " — " + enemy;
      banner.classList.add("round-banner--win");
    } else if (ally < enemy) {
      if (bannerTitle) bannerTitle.textContent = "DERROTA";
      if (bannerSub) bannerSub.textContent = ally + " — " + enemy;
      banner.classList.add("round-banner--lose");
    } else {
      if (bannerTitle) bannerTitle.textContent = "EMPATE";
      if (bannerSub) bannerSub.textContent = ally + " — " + enemy;
      banner.classList.add("round-banner--draw");
    }
    banner.classList.remove("is-hidden");
    bannerHideAt = 0;
    if (bridge && typeof bridge.set === "function") {
      try { bridge.set("partida_terminada", 1); } catch (e) { /* noop */ }
    }
  }

  function syncScoresFromGame() {
    var a = readNum("score_ally", null);
    if (a == null) a = readNum("kills_jogador", null);
    if (a != null) scoreAlly = Math.max(0, Math.round(a));
    var e = readNum("score_enemy", null);
    if (e == null) e = readNum("kills_inimigo", null);
    if (e != null) scoreEnemy = Math.max(0, Math.round(e));
    setText(scoreAllyEl, scoreAlly);
    setText(scoreEnemyEl, scoreEnemy);
  }

  function syncAllyFromGame() {
    var raw = readStr("fantasia_escolhida", null);
    if (raw) {
      var id = normalizeAgentId(raw);
      if (AGENTS[id] && TEAM_ALLY[0] && TEAM_ALLY[0].id !== id) {
        TEAM_ALLY[0].id = id;
        renderPortraits(document.getElementById("portraitsAlly"), TEAM_ALLY, false);
      }
    }
    var vida = readNum("vida", TEAM_ALLY[0] ? TEAM_ALLY[0].hp : 100);
    if (allyPortraitEls[0]) setPortraitHp(allyPortraitEls[0], vida);
  }

  function syncEnemyFromGame() {
    for (var i = 0; i < TEAM_ENEMY.length; i++) {
      var slot = i + 1;
      // Opcional: inimigo_agente_N (nome) ou número; senão mapa fixo do atributo agente
      var agentRaw = readStr("inimigo_agente_" + slot, null);
      if (agentRaw != null) {
        var asNum = Number(agentRaw);
        if (Number.isFinite(asNum) && ENEMY_AGENTE_TO_ID[asNum]) {
          setEnemyAgent(i, ENEMY_AGENTE_TO_ID[asNum]);
        } else {
          setEnemyAgent(i, agentRaw);
        }
      } else {
        setEnemyAgent(i, ENEMY_AGENTE_TO_ID[slot]);
      }

      var hp = readNum("inimigo_hp_" + slot, null);
      if (hp == null) hp = TEAM_ENEMY[i].hp;
      setPortraitHp(enemyPortraitEls[i], hp);
    }
  }

  function syncFromGame() {
    if (!inGame) return;
    const vida = readNum("vida", null);
    if (vida != null) setText(healthEl, Math.max(0, Math.round(vida)));
    const colete = readNum("colete", null);
    if (colete != null) setText(shieldEl, Math.max(0, Math.round(colete)));
    var mag = readNum("quant_bala", null);
    if (mag == null) mag = readNum("municao", null);
    if (mag != null) setText(ammoMagEl, Math.max(0, Math.round(mag)));
    var reserva = readNum("balas_pente", null);
    if (reserva == null) reserva = readNum("reserva", null);
    if (reserva != null) setText(ammoReserveEl, Math.max(0, Math.round(reserva)));
    const creditos = readNum("creditos", null);
    if (creditos != null) setText(creditsEl, Math.max(0, Math.round(creditos)));

    var tRaw = bridge.get("timer");
    if (tRaw != null && tRaw !== "") {
      usingGameTimer = true;
      var t = Number(tRaw);
      if (Number.isFinite(t)) {
        seconds = Math.max(0, Math.round(t));
        setText(timerEl, formatTime(seconds));
        if (seconds > 0) matchReady = true;
        else if (matchReady) showMatchEnd();
      }
    }

    syncAllyFromGame();
    syncEnemyFromGame();
    syncScoresFromGame();

    var ended = readNum("partida_terminada", 0);
    if (ended < 1) matchReady = true;
    else if (matchReady) showMatchEnd();
  }

  function tickTimer() {
    if (matchEnded) {
      setText(timerEl, "0:00");
      return;
    }
    if (inGame && usingGameTimer) return;
    if (seconds <= 0) {
      setText(timerEl, "0:00");
      if (!inGame || matchReady) showMatchEnd();
      return;
    }
    if (inGame) matchReady = true;
    seconds -= 1;
    setText(timerEl, formatTime(seconds));
    if (seconds <= 0 && (!inGame || matchReady)) showMatchEnd();
  }

  if (!inGame) {
    document.body.classList.add("hud-preview");
    seconds = 5;
    scoreAlly = 3;
    scoreEnemy = 2;
    setText(scoreAllyEl, scoreAlly);
    setText(scoreEnemyEl, scoreEnemy);
    setText(timerEl, formatTime(seconds));
    setText(healthEl, "100");
    for (var i = 0; i < TEAM_ENEMY.length; i++) setPortraitHp(enemyPortraitEls[i], 100 - i * 18);
    if (allyPortraitEls[0]) setPortraitHp(allyPortraitEls[0], 100);
    if (banner) {
      banner.classList.remove("is-hidden");
      bannerHideAt = performance.now() + 4000;
    }
  } else {
    setText(scoreAllyEl, "0");
    setText(scoreEnemyEl, "0");
    setText(timerEl, formatTime(seconds));
    setText(healthEl, "100");
    for (var j = 0; j < TEAM_ENEMY.length; j++) setPortraitHp(enemyPortraitEls[j], 100);
    syncFromGame();
  }

  setInterval(tickTimer, 1000);

  function hideBannerIfDue(now) {
    if (!banner || banner.classList.contains("is-hidden") || matchEnded) return;
    if (bannerHideAt && now >= bannerHideAt) banner.classList.add("is-hidden");
  }

  function selectWeapon(slot) {
    const s = String(slot);
    weapons.forEach(function (w) {
      w.classList.toggle("weapon--active", w.dataset.slot === s);
    });
    if (bridge && typeof bridge.set === "function") {
      try { bridge.set("arma", Number(s) || s); } catch (e) { /* noop */ }
    }
  }

  document.addEventListener("keydown", function (e) {
    if (e.key === "1" || e.key === "2" || e.key === "3") selectWeapon(e.key);
    if (e.key === "Escape" && banner && !matchEnded) banner.classList.add("is-hidden");
  });
  weapons.forEach(function (w) {
    w.style.pointerEvents = "auto";
    w.style.cursor = "pointer";
    w.addEventListener("click", function () {
      selectWeapon(w.dataset.slot);
    });
  });

  function frame(now) {
    syncFromGame();
    hideBannerIfDue(now);
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();

