/* HUD Fase — mock Valorant (design 1920×1080) */

:root {
  --ink: #f4f6f8;
  --ink-dim: rgba(244, 246, 248, 0.62);
  --ally: #3d6664;
  --ally-deep: #2a4a48;
  --enemy: #7a3030;
  --enemy-deep: #4a2222;
  --cyan: #7cfaf4;
  --cyan-dim: rgba(124, 250, 244, 0.55);
  --panel: #2a2e33;
  --timer-bg: #3a3f45;
  --frame: rgba(255, 255, 255, 0.85);
  --font: "Rajdhani", "Segoe UI", system-ui, sans-serif;
  /* Hexágono alongado (pontas L/R) — mesmo do timer, placar 11/9 */
  --hex-clip: polygon(14px 0, calc(100% - 14px) 0, 100% 50%, calc(100% - 14px) 100%, 14px 100%, 0 50%);
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html, body {
  width: 100%;
  height: 100%;
  background: transparent !important;
}

body {
  font-family: var(--font);
  color: var(--ink);
  overflow: hidden;
  user-select: none;
}

/* Preview standalone (arquivo aberto no browser) */
body.hud-preview {
  background: #000 !important;
}

.hud {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 100%;
  pointer-events: none;
}

/* ---------- Spectators ---------- */
.spectators {
  position: absolute;
  top: 14px;
  right: 22px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.14em;
  color: var(--ink-dim);
  z-index: 5;
}

.spectators span { color: var(--ink); }

/* ---------- Scoreboard ---------- */
.scoreboard {
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: stretch;
  z-index: 10;
  filter: drop-shadow(0 4px 14px rgba(0, 0, 0, 0.45));
}

/* Container hexagonal: ponta = placar; restante = fill colorido por cima.
   Sem clip-path no .team — senão a barra de HP (abaixo) some. */
.team {
  position: relative;
  display: flex;
  align-items: stretch;
  height: 40px;
  min-width: 420px;
  overflow: visible;
}

.team::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  background: var(--panel);
  clip-path: var(--hex-clip);
  pointer-events: none;
}

.team--ally {
  margin-right: 10px;
}

.team--enemy {
  margin-left: 10px;
}

.score {
  position: absolute;
  top: 0;
  bottom: 0;
  z-index: 1;
  display: grid;
  place-items: center;
  min-width: 56px;
  padding: 0 16px 0 20px;
  font-size: 28px;
  font-weight: 700;
  line-height: 1;
  color: var(--ink);
  background: transparent;
  pointer-events: none;
}

/* Ally: ponta direita (perto do timer) = placar */
.team--ally .score {
  right: 0;
  padding: 0 20px 0 16px;
}

/* Enemy: ponta esquerda (perto do timer) = placar */
.team--enemy .score {
  left: 0;
  padding: 0 16px 0 20px;
}

.team__fill {
  position: absolute;
  top: 0;
  bottom: 0;
  z-index: 2;
  display: flex;
  align-items: stretch;
  gap: 8px;
  overflow: visible;
}

.team__fill::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

.team--ally .team__fill {
  left: 0;
  right: 55px; /* ponta direita = placar */
  padding: 0 28px 0 22px;
  justify-content: flex-end;
}

.team--ally .team__fill::before {
  background: linear-gradient(90deg, var(--ally-deep), var(--ally));
  /* pontas dos dois lados (igual ao timer) */
  clip-path: var(--hex-clip);
}

.team--enemy .team__fill {
  left: 55px; /* ponta esquerda = placar */
  right: 0;
  padding: 0 22px 0 28px;
  justify-content: flex-start;
}

.team--enemy .team__fill::before {
  background: linear-gradient(90deg, var(--enemy), var(--enemy-deep));
  clip-path: var(--hex-clip);
}

.portraits {
  position: relative;
  z-index: 1;
  display: flex;
  gap: 16px;
  align-items: stretch;
  height: 100%;
  overflow: visible;
}

.portrait {
  width: 40px;
  height: 100%;
  position: relative;
  flex-shrink: 0;
  overflow: visible;
  z-index: 3;
}

.portrait__img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center top;
  background: transparent;
}

.portrait--dim .portrait__img {
  filter: grayscale(0.45) brightness(0.7);
}

.portrait__hp {
  position: absolute;
  left: 50%;
  bottom: -15px;
  transform: translateX(-50%);
  width: 28px;
  height: 5px;
  border-radius: 3px;
  overflow: hidden;
  /* Trilha vazia (fundo) */
  background: rgba(255, 255, 255, 0.22);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.35);
}

.portrait__hp-fill {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: inherit;
  transform-origin: left center;
  transform: scaleX(1);
  /* Aliados: barra branca */
  background: rgba(255, 255, 255, 0.95);
}

.portrait__hp--enemy .portrait__hp-fill {
  /* Inimigos: barra vermelha sobre trilha clara */
  background: #e85a5a;
}

.portrait__hp--dim .portrait__hp-fill,
.portrait--dim .portrait__hp-fill {
  background: rgba(255, 255, 255, 0.28);
}

.portrait__hp--enemy.portrait__hp--dim .portrait__hp-fill,
.portrait--dim .portrait__hp--enemy .portrait__hp-fill {
  background: rgba(180, 80, 80, 0.45);
}

.timer-wrap {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.timer {
  min-width: 96px;
  height: 46px;
  display: grid;
  place-items: center;
  font-size: 30px;
  font-weight: 700;
  letter-spacing: 0.04em;
  background: var(--timer-bg);
  clip-path: var(--hex-clip);
  padding: 0 20px;
}

.timer-chevron {
  width: 0;
  height: 0;
  margin-top: 2px;
  border-left: 6px solid transparent;
  border-right: 6px solid transparent;
  border-top: 7px solid rgba(255, 255, 255, 0.85);
}

.spike-icon {
  width: 22px;
  height: 22px;
  color: #e85a5a;
  display: grid;
  place-items: center;
}
.spike-icon svg { width: 100%; height: 100%; }

/* ---------- Minimap ---------- */
.minimap {
  position: absolute;
  top: 16px;
  left: 18px;
  width: min(40vw, 410px);
  height: min(40vw, 410px);
  z-index: 8;
}

.minimap__ring {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  padding: 8px;
  background:
    radial-gradient(circle at 50% 50%, transparent 60%, rgba(8, 10, 12, 0.55) 78%, rgba(0, 0, 0, 0.9) 100%);
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.18), 0 10px 28px rgba(0, 0, 0, 0.4);
}

.minimap__inner {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  overflow: hidden;
}

.minimap__map {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: center;
}

/* ---------- Round banner ---------- */
.round-banner {
  position: absolute;
  top: 26%;
  left: 50%;
  transform: translateX(-50%);
  z-index: 12;
