/**
 * Loading da fase: escuta transmita(loading_iniciar_fase) via __blkHtmlUi.on.
 * Só aparece quando o bloco Transmita roda; some quando os assets estabilizam.
 */
(function () {
  var root = document.getElementById("loading");
  var statusEl = document.getElementById("status");
  var listEl = document.getElementById("list");
  var barFill = document.getElementById("barFill");
  var hintEl = document.getElementById("hint");
  var maxPending = 0;
  var lastMsg = "";
  var lastList = "";
  var bootDone = true;
  var armed = false;
  var sawPending = false;
  var mountAt = 0;

  function ui() {
    return window.__blkHtmlUi;
  }

  function readLoading() {
    var api = ui();
    if (api && typeof api.loading === "function") {
      try { return api.loading() || {}; } catch (e) { /* ignore */ }
    }
    return {};
  }

  function setText(el, value) {
    if (!el) return;
    var next = String(value == null ? "" : value);
    if (el.textContent !== next) el.textContent = next;
  }

  function renderList(labels) {
    if (!listEl) return;
    var arr = Array.isArray(labels) ? labels : [];
    var sig = arr.join("|");
    if (sig === lastList) return;
    lastList = sig;
    listEl.innerHTML = "";
    if (!arr.length) {
      listEl.hidden = true;
      return;
    }
    listEl.hidden = false;
    for (var i = 0; i < arr.length; i++) {
      var li = document.createElement("li");
      li.textContent = arr[i];
      listEl.appendChild(li);
    }
  }

  function hideOverlayNow() {
    document.documentElement.style.background = "transparent";
    document.body.style.background = "transparent";
    if (root) {
      root.classList.add("is-done", "is-hidden");
    }
  }

  function finishBoot() {
    if (bootDone) return;
    bootDone = true;
    armed = false;
    hideOverlayNow();
    setText(statusEl, "Pronto");
    setText(hintEl, "Pronto");
    if (barFill) barFill.style.width = "100%";
    var api = ui();
    if (api && typeof api.phaseLoadingDone === "function") {
      try { api.phaseLoadingDone(); } catch (e) { /* ignore */ }
    }
  }

  function tick() {
    if (bootDone || !armed) return;

    var info = readLoading();
    var pending = Number(info.pending) || 0;
    var ready = !!info.ready;
    var labels = info.labels || [];
    var msg = info.message || (pending > 0
      ? "Carregando fase…"
      : "Preparando fase…");

    if (pending > 0) sawPending = true;
    if (pending > maxPending) maxPending = pending;

    if (String(msg) !== lastMsg) {
      lastMsg = String(msg);
      setText(statusEl, lastMsg);
    }
    renderList(labels);

    var pct = 8;
    if (ready && pending === 0 && (sawPending || maxPending > 0)) pct = 100;
    else if (maxPending > 0) {
      pct = Math.max(8, Math.min(95, ((maxPending - pending) / maxPending) * 100));
    }
    if (barFill) barFill.style.width = pct + "%";

    var waited = performance.now() - mountAt;
    // Espera assets da fase (scene-load) começarem; senão some no grace do menu.
    var canFinish =
      ready &&
      pending === 0 &&
      (sawPending || waited >= 4500);

    if (canFinish) {
      finishBoot();
      return;
    }

    if (root) root.classList.remove("is-done", "is-hidden");

    setText(hintEl, pending > 0
      ? (pending + " restante" + (pending > 1 ? "s" : ""))
      : "Aguarde o mapa e os atores carregarem");
    requestAnimationFrame(tick);
  }

  function arm() {
    bootDone = false;
    armed = true;
    sawPending = false;
    maxPending = 0;
    lastMsg = "";
    lastList = "";
    mountAt = performance.now();
    if (root) root.classList.remove("is-done", "is-hidden");
    setText(statusEl, "Carregando fase…");
    setText(hintEl, "Aguarde o mapa e os atores carregarem");
    if (barFill) barFill.style.width = "8%";
    requestAnimationFrame(tick);
  }

  hideOverlayNow();

  function bind() {
    var api = ui();
    if (!api || typeof api.on !== "function") {
      setTimeout(bind, 50);
      return;
    }
    api.on("loading_iniciar_fase", function () {
      arm();
    });
  }
  bind();
})();

