const grid = document.getElementById("roster_grid");
const countEl = document.getElementById("roster_count");
const previewName = document.getElementById("preview_name");
const previewDesc = document.getElementById("preview_desc");
const btnConfirm = document.getElementById("btn_confirm");

const COUNTDOWN_SEC = 20;
let secondsLeft = COUNTDOWN_SEC;
let launching = false;
let tickTimer = null;

const names = Object.keys(characters);
if (countEl) countEl.textContent = String(names.length);

function displayNameOf(id) {
  return id.charAt(0).toUpperCase() + id.slice(1);
}

function updateConfirmLabel() {
  if (!btnConfirm || launching) return;
  btnConfirm.textContent = "Confirmar (" + secondsLeft + ")";
}

function stopCountdown() {
  if (tickTimer) {
    clearInterval(tickTimer);
    tickTimer = null;
  }
}

/** Clique do usuário OU timer a zero → iniciar_jogo() via binding do botão. */
function goToPhase() {
  if (launching || !btnConfirm) return;
  launching = true;
  stopCountdown();
  btnConfirm.textContent = "Entrando…";
  try {
    btnConfirm.click();
  } catch (e) {}
  btnConfirm.disabled = true;
}

function selectCharacter(id) {
  const data = characters[id];
  if (!data) return;

  const displayName = displayNameOf(id);
  if (previewName) previewName.textContent = displayName.toUpperCase();
  if (previewDesc) previewDesc.textContent = data.description || "";

  grid.querySelectorAll(".char-card").forEach((card) => {
    card.classList.toggle("focused", card.dataset.id === id);
  });

  if (btnConfirm) btnConfirm.disabled = false;
}

names.forEach((name, position) => {
  const data = characters[name];
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "char-card characters";
  const displayName = displayNameOf(name);
  btn.dataset.id = name;
  btn.dataset.name = displayName;
  btn.dataset.description = data.description || "";
  btn.dataset.position = String(position);
  btn.title = displayName;

  const params = {
    name: displayName,
    id: name,
    description: data.description || "",
    position: position,
  };
  if (window.__blkHtmlUi && typeof window.__blkHtmlUi.bind === "function") {
    window.__blkHtmlUi.bind(btn, params);
  }
  btn.onclick = function () {
    selectCharacter(name);
    if (window.__blkHtmlUi && typeof window.__blkHtmlUi.params === "function") {
      window.__blkHtmlUi.params(params);
    }
  };

  const img = document.createElement("img");
  img.src = data.img;
  img.alt = displayName;
  img.draggable = false;

  btn.appendChild(img);
  grid.appendChild(btn);
});

selectCharacter("astra");
updateConfirmLabel();

(function setupMapSelect() {
