      }
    } catch (e) {}
    document.querySelectorAll(".map-btn").forEach(function (b) {
      b.classList.toggle("is-active", b.dataset.scene === sceneId);
    });
  }
  function showChars() {
    if (mapScreen) mapScreen.classList.add("is-hidden");
    if (charScreen) charScreen.classList.remove("is-hidden");
  }
  function showMaps() {
    if (charScreen) charScreen.classList.add("is-hidden");
    if (mapScreen) mapScreen.classList.remove("is-hidden");
  }
  document.querySelectorAll(".map-btn").forEach(function (btn) {
    btn.addEventListener("click", function () {
      setMap(btn.dataset.scene, btn.dataset.map);
      showChars();
    });
  });
  if (btnBack) {
    btnBack.addEventListener("click", function () {
      if (launching) return;
      showMaps();
    });
  }
  setMap("scene_ascent", "ascent");
  showMaps();
})();


if (btnConfirm) {
  btnConfirm.addEventListener("click", function () {
    // Clique manual: o binding do Blocking dispara neste mesmo evento.
    launching = true;
    stopCountdown();
    btnConfirm.disabled = true;
    btnConfirm.textContent = "Entrando…";
  });
}

tickTimer = setInterval(function () {
  if (launching) return;
  secondsLeft -= 1;
  if (secondsLeft <= 0) {
    secondsLeft = 0;
    updateConfirmLabel();
    goToPhase();
    return;
  }
  updateConfirmLabel();
}, 1000);

structuralOverrides.ui/Character_Select_Menu/style.css:
*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  width: 100%;
  height: 100%;
  background: transparent;
  color: #f4f7ff;
  font-family: "Segoe UI", system-ui, sans-serif;
  overflow: hidden;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
}

.select-screen {
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  padding: 18px 22px 16px;
  gap: 14px;
  background: transparent;
}

.top-bar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  flex-shrink: 0;
}

.team-slots {
  display: flex;
  gap: 10px;
}

.slot {
  width: 72px;
  height: 88px;
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(8, 12, 22, 0.55);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  transition: border-color 0.15s, transform 0.15s, box-shadow 0.15s;
}

.slot:hover {
  border-color: rgba(255, 214, 90, 0.55);
  transform: translateY(-1px);
}

.slot.active-slot {
  border-color: rgba(255, 214, 90, 0.9);
  box-shadow: 0 0 0 1px rgba(255, 214, 90, 0.35), 0 8px 24px rgba(0, 0, 0, 0.35);
}

.slot.filled {
  border-color: rgba(120, 220, 160, 0.55);
}

.slot-img {
  width: 48px;
  height: 48px;
  object-fit: cover;
  border-radius: 10px;
}

.slot-plus {
  font-size: 28px;
  font-weight: 300;
  color: rgba(255, 255, 255, 0.45);
  line-height: 1;
}

.slot.filled .slot-plus {
  display: none;
}

.slot-name {
  font-size: 10px;
  color: rgba(255, 255, 255, 0.7);
  max-width: 64px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.top-title {
  text-align: right;
}

.title-kicker {
  display: inline-block;
  font-size: 10px;
  letter-spacing: 0.18em;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.45);
  margin-bottom: 4px;
}

.top-title h1 {
  margin: 0;
  font-size: 22px;
  font-weight: 800;
  letter-spacing: 0.02em;
  text-shadow: 0 2px 16px rgba(0, 0, 0, 0.45);
}

.main {
  position: relative;
  flex: 1;
  min-height: 0;
  display: flex;
  align-items: stretch;
  gap: 16px;
}

.roster-panel {
  display: flex;
  flex-direction: column;
  width: min(400px, 38vw);
  flex-shrink: 0;
  min-height: 0;
  overflow: hidden;
  padding: 12px;
  border-radius: 18px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.roster-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.55);
  flex-shrink: 0;
}

.roster-count {
  min-width: 22px;
  height: 22px;
  padding: 0 7px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 214, 90, 0.16);
  color: #ffd65a;
  font-size: 11px;
}

.roster-grid {
  flex: 1;
  min-height: 0;
  overflow: auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  align-content: start;
  padding-right: 4px;
}

.roster-grid::-webkit-scrollbar {
  width: 6px;
}

.roster-grid::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.18);
  border-radius: 999px;
}

.char-card {
  position: relative;
  aspect-ratio: 1;
  border-radius: 12px;
  border: 2px solid rgba(255, 255, 255, 0.1);
  background: rgba(0, 0, 0, 0.35);
  overflow: hidden;
  transition: border-color 0.15s, transform 0.15s, box-shadow 0.15s;
}

.char-card:hover {
  border-color: rgba(255, 255, 255, 0.35);
  transform: translateY(-1px);
}

.char-card.focused {
  border-color: #ffd65a;
  box-shadow: 0 0 0 1px rgba(255, 214, 90, 0.55), 0 0 18px rgba(255, 214, 90, 0.25);
  transform: scale(1.03);
  z-index: 1;
}

.char-card.picked {
  border-color: rgba(90, 220, 140, 0.85);
}

.char-card img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.char-card .face {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
  font-weight: 800;
  letter-spacing: -0.04em;
  color: rgba(255, 255, 255, 0.92);
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.45);
}

.char-card .lvl {
  position: absolute;
  left: 5px;
  bottom: 5px;
  min-width: 22px;
  height: 22px;
  padding: 0 5px;
  border-radius: 6px;
  background: linear-gradient(180deg, #ffe27a, #d9a21a);
  color: #1a1200;
  font-size: 10px;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.35);
}

.char-card .picked-mark {
  position: absolute;
  right: 4px;
  top: 4px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #2ecc71;
  color: #fff;
  font-size: 11px;
  font-weight: 800;
  display: none;
  align-items: center;
  justify-content: center;
}

.char-card.picked .picked-mark {
  display: inline-flex;
}

.preview-panel {
  /* Alinha à direita com o mesmo padding do select-screen (22px) — igual ao título. */
  position: absolute;
  top: 4px;
  right: 0;
  left: 0;
  z-index: 5;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: flex-end;
  padding-right: 0;
  margin: 0;
  border: 0;
  background: transparent;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  box-shadow: none;
  border-radius: 0;
  pointer-events: none;
  box-sizing: border-box;
}

.preview-meta {
  position: relative;
  z-index: 2;
  max-width: min(520px, 58%);
  text-align: right;
}

.difficulty {
  margin: 0 0 6px;
  font-size: 12px;
  font-weight: 700;
  color: #ff8a5c;
}

.char-name {
  margin: 0;
  font-size: clamp(36px, 4.8vw, 64px);
  font-weight: 900;
  line-height: 0.95;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  text-align: right;
  color: #ffffff;
  text-shadow: 0 2px 18px rgba(0, 0, 0, 0.55);
  white-space: nowrap;
  overflow: visible;
}

.char-level {
  margin: 8px 0 0;
  font-size: 13px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.7);
}

.tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 12px;
}

.tag {
  padding: 4px 9px;
  border-radius: 7px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(0, 0, 0, 0.35);
  font-size: 11px;
  color: rgba(255, 255, 255, 0.82);
}

.preview-stage {
  position: relative;
  flex: 1;
  min-height: 160px;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  margin: 8px 0 10px;
}

.preview-glow {
  position: absolute;
  inset: 10% 18% 18%;
  background: radial-gradient(ellipse at center, rgba(120, 170, 255, 0.28), transparent 70%);
  filter: blur(8px);
  pointer-events: none;
}

.preview-portrait {
  position: relative;
  z-index: 1;
  width: min(58%, 220px);
  aspect-ratio: 1;
  border-radius: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: clamp(48px, 8vw, 84px);
  font-weight: 900;
  color: #fff;
  text-shadow: 0 8px 28px rgba(0, 0, 0, 0.5);
  transform: translateY(8px);
  transition: transform 0.2s ease, filter 0.2s ease;
}

.preview-portrait.pulse {
  transform: translateY(0) scale(1.04);
}

.preview-pedestal {
  position: absolute;
  bottom: 8%;
  width: 54%;
  height: 18px;
  border-radius: 50%;
  background: radial-gradient(ellipse at center, rgba(180, 210, 255, 0.55), rgba(40, 60, 100, 0.15) 70%, transparent);
  box-shadow: 0 0 28px rgba(120, 170, 255, 0.35);
}

.char-desc {
  position: relative;
  z-index: 2;
  margin: 14px 0 0;
  max-width: min(36ch, 100%);
  font-size: 14px;
  line-height: 1.45;
  font-weight: 600;
  color: #f0e14a;
  text-align: right;
  text-shadow: 0 1px 10px rgba(0, 0, 0, 0.45);
  min-height: 0;
  align-self: flex-end;
}

.bottom-bar {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  flex-shrink: 0;
}

.btn {
  min-width: 120px;
  height: 40px;
  padding: 0 18px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.02em;
  transition: background 0.15s, transform 0.15s, opacity 0.15s;
}

.btn:active {
  transform: translateY(1px);
}

.btn.ghost {
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: rgba(8, 12, 22, 0.45);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  color: rgba(255, 255, 255, 0.8);
}

.btn.ghost:hover {
  background: rgba(255, 255, 255, 0.08);
}

.btn.primary {
  background: linear-gradient(180deg, #ffe27a, #e0ad2a);
  color: #1a1200;
  box-shadow: 0 8px 22px rgba(224, 173, 42, 0.28);
}

.btn.primary:hover:not(:disabled) {
  filter: brightness(1.05);
}

.btn.primary:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

@media (max-width: 720px) {
  .main {
    grid-template-columns: 1fr;
  }

  .preview-panel {
    top: auto;
    bottom: 8px;
    padding-right: 0;
  }

  .preview-meta {
    max-width: min(280px, 72%);
  }

  .char-name {
    font-size: clamp(28px, 8vw, 44px);
    white-space: normal;
  }

  .top-bar {
    flex-direction: column;
  }

  .top-title {
    text-align: left;
  }
}


.map-select {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: radial-gradient(ellipse at center, rgba(12,18,32,.55), rgba(4,6,12,.82));
}
.map-select.is-hidden { display: none; }
.select-screen.is-hidden { display: none; }
.map-select__card {
  min-width: min(92vw, 420px);
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 28px 26px 24px;
  border-radius: 18px;
  border: 1px solid rgba(255,255,255,.14);
  background: rgba(8,12,22,.72);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 18px 48px rgba(0,0,0,.45);
}
.map-select__kicker {
  font-size: 11px;
  letter-spacing: .28em;
  opacity: .7;
}
.map-select__title {
  margin: 0;
  font-size: 28px;
  font-weight: 700;
  letter-spacing: .04em;
}
.map-select__sub {
  margin: 0 0 8px;
  font-size: 13px;
  opacity: .75;
  line-height: 1.4;
}
.map-select__list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.map-btn {
  padding: 14px 16px;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,.16);
  background: rgba(255,255,255,.06);
  font-weight: 700;
  letter-spacing: .14em;
  transition: border-color .15s, background .15s, transform .15s;
}
.map-btn:hover {
  border-color: rgba(255,214,90,.7);
  background: rgba(255,214,90,.12);
  transform: translateY(-1px);
}
.map-btn.is-active {
  border-color: rgba(120,220,160,.85);
  background: rgba(120,220,160,.16);
}
